package com.cenedu.backend.ai.problem.render;
import com.cenedu.backend.domain.problem.authoring.diagram.*; import com.cenedu.backend.domain.problem.authoring.semantic.evaluation.SemanticResolvedValue; import java.util.*;
public final class SolidGeometrySvgRenderer { public String render(SolidGeometryDiagramSpecV1 s){return render(s,Map.of());} public String render(SolidGeometryDiagramSpecV1 s,Map<String,SemanticResolvedValue> values){int p=s.viewport().padding(),w=s.viewport().width(),h=s.viewport().height(),dx=40,dy=23;var b=new StringBuilder("<polygon points=\"").append(p).append(",").append(h-p).append(" ").append(w-p).append(",").append(h-p).append(" ").append(w-p-dx).append(",").append(p+dy).append(" ").append(p+dx).append(",").append(p).append("\" fill=\"none\" stroke=\"#000000\"/>");for(var label:s.labels()){String text=label.labelTemplate();var value=values.get(label.valueKey());if(value!=null)text+=" "+value.canonicalValue();b.append("<text x=\"").append(p+8).append("\" y=\"").append(p+18).append("\">").append(text.replace("&","&amp;").replace("<","&lt;").replace(">","&gt;")).append("</text>");}return b.toString();} }
